<template><div class="page"><div class="page-head"><div><h2>退款记录</h2><p>会员卡退款按资金事实处理：现场退款直接出款，财务退款进入 ERP 应付。</p></div></div><div class="toolbar"><el-input v-model="query.keyword" clearable placeholder="退款号 / 开卡单 / 客户 / 手机号" @keyup.enter="reload"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option label="待退款" value="pending"/><el-option label="退款失败" value="failed"/><el-option label="已退款" value="paid"/></el-select><el-button type="primary" @click="reload">查询</el-button><el-button @click="reset">重置</el-button></div><el-table :data="rows" v-loading="loading"><el-table-column label="客户" min-width="190"><template #default="{row}"><b>{{ row.holder_name }}</b><div class="sub">{{ mask(row.holder_mobile) }}</div></template></el-table-column><el-table-column label="退款单" min-width="220"><template #default="{row}">{{ row.refund_no }}<div class="sub">{{ time(row.create_at) }}</div></template></el-table-column><el-table-column label="金额" width="130"><template #default="{row}"><b>¥{{ money(row.refund_amount) }}</b></template></el-table-column><el-table-column label="方式" width="120"><template #default="{row}">{{ row.refund_mode==='immediate'?'现场退款':'ERP 财务退款' }}</template></el-table-column><el-table-column prop="capital_account_name" label="出款账户" min-width="150"><template #default="{row}">{{ row.capital_account_name||'—' }}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><MemberCardStatusTag :value="row.status"/></template></el-table-column><el-table-column label="操作" width="120" align="right"><template #default="{row}"><el-button v-if="row.status==='failed'" link type="warning" @click="retry(row)">重试财务</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="query.page" v-model:page-size="query.limit" layout="total,prev,pager,next" :total="total" @current-change="load"/></div></div></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{getCardRefunds,retryCardRefundFinance}from'../../api';import MemberCardStatusTag from'../../components/MemberCardStatusTag.vue';const query=reactive({keyword:'',status:'',page:1,limit:15}),rows=ref<any[]>([]),total=ref(0),loading=ref(false);const money=(v:any)=>Number(v||0).toFixed(2),time=(v:any)=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}):'—',mask=(v:string)=>/^\d{11}$/.test(v||'')?`${v.slice(0,3)}****${v.slice(-4)}`:(v||'—');const load=async()=>{loading.value=true;try{const d:any=(await getCardRefunds(query)).data||{};rows.value=d.data||[];total.value=d.total||0}finally{loading.value=false}};const reload=()=>{query.page=1;load()};const reset=()=>{query.keyword='';query.status='';reload()};const retry=async(row:any)=>{await ElMessageBox.confirm('将重新创建或确认 ERP 退款应付，原退款单和失败原因会保留。','重试退款财务',{type:'warning'});await retryCardRefundFinance(row.id);ElMessage.success('已重试退款财务');load()};onMounted(load)</script>
<style scoped>.page{min-height:100%;padding:20px;box-sizing:border-box;background:var(--el-bg-color)}.page-head{margin-bottom:20px}.page-head h2{margin:0;font-size:20px;font-weight:500}.page-head p{margin:6px 0 0;color:var(--el-text-color-secondary)}.toolbar{display:flex;gap:10px;margin-bottom:14px;padding:14px 16px;border-radius:4px;background:var(--el-fill-color-lighter)}.toolbar .el-input{width:360px}.toolbar .el-select{width:150px}.sub{margin-top:5px;color:var(--el-text-color-secondary);font-size:12px}.pagination{display:flex;justify-content:flex-end;margin-top:16px}</style>
